//! truetype.library's functions: a TrueType file rendered into font
//! images, one size at a time, since 1.2 its glyphs as outlines, since
//! 1.4 a font of a collection, its names and its tables, since 1.5 one
//! glyph rendered by its number, since 1.6 an OpenType file whose
//! glyphs are of cubic curves (a CFF table's), since 1.7 a font
//! whose glyphs are pictures, of coverage or of colour, and since 1.8
//! a variable font at a place on its axes.
//! Open it with OpenLibrary("truetype.library", 1).
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/truetype_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const utility = @import("../libs/utility/utility.zig");
const graphics = @import("../libs/graphics/graphics.zig");
const truetype = @import("../libs/truetype/truetype.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "truetype.library";

