    pub const RenderFontImage = libraries.lvo(5);
    pub const CloseOutline = libraries.lvo(6);
    pub const GlyphIndex = libraries.lvo(7);
    pub const GlyphMetrics = libraries.lvo(8);
    pub const GlyphSegments = libraries.lvo(9);
    pub const FontMetrics = libraries.lvo(10);
    pub const Kerning = libraries.lvo(11);
    pub const GlyphVariant = libraries.lvo(12);
    pub const FontName = libraries.lvo(13);
    pub const FontTable = libraries.lvo(14);
    pub const RenderGlyph = libraries.lvo(15);
    pub const FontAxes = libraries.lvo(16);
    pub const FontInstance = libraries.lvo(17);
    pub const FontCoordinates = libraries.lvo(18);
    pub const GlyphAdvance = libraries.lvo(19);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const OpenOutline = *const fn (*TrueTypeBase, [*]const u8, u32, ?[*]const utility.TagItem) callconv(.c) ?*truetype.Outline;
    pub const RenderFontImage = *const fn (*TrueTypeBase, *truetype.Outline, u32, [*]const truetype.CodeRange, u32) callconv(.c) ?*graphics.fontimage.FontImage;
    pub const CloseOutline = *const fn (*TrueTypeBase, ?*truetype.Outline) callconv(.c) void;
    pub const GlyphIndex = *const fn (*TrueTypeBase, *truetype.Outline, u32) callconv(.c) u32;
    pub const GlyphMetrics = *const fn (*TrueTypeBase, *truetype.Outline, u32, *truetype.GlyphMetrics) callconv(.c) bool;
    pub const GlyphSegments = *const fn (*TrueTypeBase, *truetype.Outline, u32, *truetype.Segments) callconv(.c) i32;
    pub const FontMetrics = *const fn (*TrueTypeBase, *truetype.Outline, *truetype.FontMetrics) callconv(.c) void;
    pub const Kerning = *const fn (*TrueTypeBase, *truetype.Outline, u32, u32) callconv(.c) i32;
    pub const GlyphVariant = *const fn (*TrueTypeBase, *truetype.Outline, u32, u32) callconv(.c) u32;
    pub const FontName = *const fn (*TrueTypeBase, *truetype.Outline, u32, [*]u8, u32) callconv(.c) u32;
    pub const FontTable = *const fn (*TrueTypeBase, *truetype.Outline, u32, *u32) callconv(.c) ?[*]const u8;
    pub const RenderGlyph = *const fn (*TrueTypeBase, *truetype.Outline, u32, u32, *truetype.GlyphImage) callconv(.c) i32;
    pub const FontAxes = *const fn (*TrueTypeBase, *truetype.Outline, ?[*]truetype.Axis, u32) callconv(.c) u32;
    pub const FontInstance = *const fn (*TrueTypeBase, *truetype.Outline, u32, ?[*]truetype.AxisValue, u32) callconv(.c) u32;
    pub const FontCoordinates = *const fn (*TrueTypeBase, *truetype.Outline, ?[*]i16, u32) callconv(.c) u32;
    pub const GlyphAdvance = *const fn (*TrueTypeBase, *truetype.Outline, u32) callconv(.c) i32;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const TrueTypeBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *TrueTypeBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The font in `size` bytes at `file`, its tables found and checked; null
    /// if it is not a font this library reads. `tags` say which font
    /// of a collection (TTA_FontIndex) and where on a variable font's axes
    /// (TTA_Axes, TTA_AxisCount); null for the first, at its default. The
    /// bytes must stay until CloseOutline. Tags since 1.4, axes since 1.8.
    pub fn OpenOutline(self: *TrueTypeBase, file: [*]const u8, size: u32, tags: ?[*]const utility.TagItem) ?*truetype.Outline {
        return libraries.call(self, LVO.OpenOutline, Fn.OpenOutline, .{ file, size, tags });
    }

    /// The outline rendered `rows` rows tall as a font image: the characters
    /// it has in the `count` sorted `ranges`, and its missing glyph as the
    /// default; the caller frees it with FreeVec. Null for a height of 0 or
    /// past 4096, a font with neither outlines nor pictures, ranges out of
    /// order, or no memory. Ranges since 1.3.
    pub fn RenderFontImage(self: *TrueTypeBase, outline: *truetype.Outline, rows: u32, ranges: [*]const truetype.CodeRange, count: u32) ?*graphics.fontimage.FontImage {
        return libraries.call(self, LVO.RenderFontImage, Fn.RenderFontImage, .{ outline, rows, ranges, count });
    }

    /// What OpenOutline made, given back. Null does nothing.
    pub fn CloseOutline(self: *TrueTypeBase, outline: ?*truetype.Outline) void {
        return libraries.call(self, LVO.CloseOutline, Fn.CloseOutline, .{outline});
    }

    /// The glyph a character is (a Unicode code point), from the font's
    /// character map; 0, the missing glyph, when it has none. Since 1.2.
    pub fn GlyphIndex(self: *TrueTypeBase, outline: *truetype.Outline, code: u32) u32 {
        return libraries.call(self, LVO.GlyphIndex, Fn.GlyphIndex, .{ outline, code });
    }

    /// A glyph's advance, left side bearing and box into `metrics`, in the
    /// font's units; false for no glyph of that number. Since 1.2.
    pub fn GlyphMetrics(self: *TrueTypeBase, outline: *truetype.Outline, glyph: u32, metrics: *truetype.GlyphMetrics) bool {
        return libraries.call(self, LVO.GlyphMetrics, Fn.GlyphMetrics, .{ outline, glyph, metrics });
    }

    /// A glyph's outline as verbs and points into `segments`' arrays, in the
    /// font's units, y up: TRUETYPE_OK, or TRUETYPEERR_ROOM with the counts
    /// it needs. Since 1.2.
    pub fn GlyphSegments(self: *TrueTypeBase, outline: *truetype.Outline, glyph: u32, segments: *truetype.Segments) i32 {
        return libraries.call(self, LVO.GlyphSegments, Fn.GlyphSegments, .{ outline, glyph, segments });
    }

    /// The font's measures into `metrics`. Since 1.2.
    pub fn FontMetrics(self: *TrueTypeBase, outline: *truetype.Outline, metrics: *truetype.FontMetrics) void {
        return libraries.call(self, LVO.FontMetrics, Fn.FontMetrics, .{ outline, metrics });
    }

    /// How much further apart the font draws `left` and `right` side by
    /// side, in its units: negative for closer. Since 1.2.
    pub fn Kerning(self: *TrueTypeBase, outline: *truetype.Outline, left: u32, right: u32) i32 {
        return libraries.call(self, LVO.Kerning, Fn.Kerning, .{ outline, left, right });
    }

    /// The glyph a character is when the variation selector `selector`
    /// follows it, from the font's variation sequences; 0 when the font has
    /// none for the two. Since 1.4.
    pub fn GlyphVariant(self: *TrueTypeBase, outline: *truetype.Outline, code: u32, selector: u32) u32 {
        return libraries.call(self, LVO.GlyphVariant, Fn.GlyphVariant, .{ outline, code, selector });
    }

    /// One of the font's names (TTNAME_FAMILY, ...) as UTF-8 into `buffer`,
    /// NUL-terminated and cut to `room` bytes; the bytes the whole name
    /// takes, 0 when the font has no such name. Since 1.4.
    pub fn FontName(self: *TrueTypeBase, outline: *truetype.Outline, name: u32, buffer: [*]u8, room: u32) u32 {
        return libraries.call(self, LVO.FontName, Fn.FontName, .{ outline, name, buffer, room });
    }

    /// The bytes of the table `tag` names (four letters, the first highest),
    /// its length into `length`; null and 0 when the font has none. They are
    /// the file's own bytes. Since 1.4.
    pub fn FontTable(self: *TrueTypeBase, outline: *truetype.Outline, tag: u32, length: *u32) ?[*]const u8 {
        return libraries.call(self, LVO.FontTable, Fn.FontTable, .{ outline, tag, length });
    }

    /// One glyph, by its number, rendered for a line `rows` tall into
    /// `image`'s bytes, with its box and advance as a font image has a
    /// glyph's: TRUETYPE_OK, or TRUETYPEERR_ROOM with the bytes it needs.
    /// `image.kind` says what a pixel is. Since 1.5.
    pub fn RenderGlyph(self: *TrueTypeBase, outline: *truetype.Outline, glyph: u32, rows: u32, image: *truetype.GlyphImage) i32 {
        return libraries.call(self, LVO.RenderGlyph, Fn.RenderGlyph, .{ outline, glyph, rows, image });
    }

    /// How many axes a variable font has, 0 for any other; up to `room` of
    /// them go into `axes`, each with its range and the value this outline
    /// was opened at. Since 1.8.
    pub fn FontAxes(self: *TrueTypeBase, outline: *truetype.Outline, axes: ?[*]truetype.Axis, room: u32) u32 {
        return libraries.call(self, LVO.FontAxes, Fn.FontAxes, .{ outline, axes, room });
    }

    /// The font's named instance `number`, counted from 0: its name as the
    /// number FontName takes, and its value on each axis into `values`, up
    /// to `room` of them, as TTA_Axes takes them. 0 when the font has no
    /// instance of that number. Since 1.8.
    pub fn FontInstance(self: *TrueTypeBase, outline: *truetype.Outline, number: u32, values: ?[*]truetype.AxisValue, room: u32) u32 {
        return libraries.call(self, LVO.FontInstance, Fn.FontInstance, .{ outline, number, values, room });
    }

    /// Where the outline was opened on each axis as shaping tables count
    /// it: -16384 to 16384 for -1 to 1, the axis' default 0. Up to `room`
    /// go into `coords`; answers the font's axis count. Since 1.8.
    pub fn FontCoordinates(self: *TrueTypeBase, outline: *truetype.Outline, coords: ?[*]i16, room: u32) u32 {
        return libraries.call(self, LVO.FontCoordinates, Fn.FontCoordinates, .{ outline, coords, room });
    }

    /// A glyph's advance in the font's units, at the outline's place on
    /// the axes; 0 for a number past the font's glyphs. Since 1.8.
    pub fn GlyphAdvance(self: *TrueTypeBase, outline: *truetype.Outline, glyph: u32) i32 {
        return libraries.call(self, LVO.GlyphAdvance, Fn.GlyphAdvance, .{ outline, glyph });
    }
};
